package com.aistock.gateway;
import com.aistock.common.*;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.http.ResponseEntity;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class ComparisonProxyTest {
 @Test void exactRoutesHeadersQueryAndBodyLimit()throws Exception{var c=mock(ComparisonPublicClient.class);when(c.get(anyString(),anyMap(),anyMap())).thenReturn(ResponseEntity.ok("{}".getBytes()));var mvc=MockMvcBuilders.standaloneSetup(new ComparisonApiProxyController(c,new ObjectMapper())).setControllerAdvice(new ApiExceptionHandler()).build();mvc.perform(get("/api/v1/comparisons/options").param("ids","SH600030,SH600276").param("period","3M").header("X-User-Id","forged").header("X-Service-Token","forged")).andExpect(status().isOk());verify(c).get(eq("comparisons/options"),eq(Map.of("ids","SH600030,SH600276","period","3M")),argThat(h->!h.containsKey("X-User-Id")&&!h.containsKey("X-Service-Token")));mvc.perform(get("/api/v1/comparisons").param("owner","forged")).andExpect(status().isUnprocessableEntity());mvc.perform(get("/api/v1/comparisons").param("upper","1","2")).andExpect(status().isUnprocessableEntity());mvc.perform(post("/api/v1/comparisons").content("x".repeat(2049))).andExpect(status().isPayloadTooLarge());mvc.perform(post("/api/v1/comparisons/options")).andExpect(status().isNotFound());assertFalse(ProxyHeaderPolicy.allowed("GET","/api/v1/comparisons;x/options"));verifyNoMoreInteractions(c);}
 @Test void independentTimeoutAndNoRetry(){var config=new ComparisonClientConfiguration();assertEquals(30000,config.comparisonOptions().readTimeoutMillis());assertEquals(2000,config.comparisonOptions().connectTimeoutMillis());assertFalse(config.comparisonOptions().isFollowRedirects());assertSame(feign.Retryer.NEVER_RETRY,config.comparisonRetryer());}
}
